+    private void validateRatePlan(NewReservation request, Room room) {
+        switch (request.ratePlan()) {
+            case CORPORATE -> {
+                if (request.companyCode() == null || request.companyCode().isBlank()) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "company code is required for corporate rate");
+                }
+                if (!PriceCalculator.CORPORATE_DISCOUNTS.containsKey(request.companyCode())) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid company code");
+                }
+            }
+            case WEEKEND_PACKAGE -> {
+                long nights = request.checkIn().datesUntil(request.checkOut()).count();
+                if (nights != 2) {
+                    throw new HotelException(
+                            ErrorCode.INVALID_REQUEST, "weekend package requires exactly 2 nights");
+                }
+                if (request.checkIn().getDayOfWeek().getValue() != 5) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must start on Friday");
+                }
+                if (request.checkOut().getDayOfWeek().getValue() != 7) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must end on Sunday");
+                }
+            }
+            case LONG_STAY -> {
+                long nights = request.checkIn().datesUntil(request.checkOut()).count();
+                if (nights < 7) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
+                }
+            }
+        }
+    }
+
     public Reservation find(long reservationId) {
         return store.find(reservationId)
                 .orElseThrow(() -> new HotelException(
@@ -84,8 +119,10 @@ public final class ReservationService {
             throw notAllowed(reservation, "cancel");
         }
         BigDecimal refund = switch (reservation.ratePlan()) {
-            case STANDARD -> reservation.amountPaid();
+            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
             case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
+            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().divide(
+                    new BigDecimal("2"), 2, RoundingMode.HALF_EVEN));
         };
         reservation.cancel(refund);
         return reservation;
